h1,p{
    text-align: center;
    color: rgb(255, 255, 255);
}
p{
    font-style: italic;
}
body{
    background-color: rgb(74, 74, 173);
    height: 100%;
    text-align: center;
    width: 40%;
    min-width: 40%;
    min-height: 100%;
    margin: auto;
    
}
fieldset{
    background-color: rgb(38, 38, 83);
    margin: auto;
    text-align: left;
    border: none;
    padding: 3%;
   
}
form{
    color: rgb(255, 255, 255);
    border: solid;
    border-color: rgb(38, 38, 83);
    display: inline-block ;
}
#submit{
    width: 60%;
    height: 20px;
    display: block;
    margin: auto;
}
#name,#email,#age,#role,#feature,#comment{
    width: 100%;
    display: block;

    
}

.body{
    padding: 15px;
    border-radius: 5px;
    background: rgb(238, 238, 238);
    display: flex;
    flex-direction: column;
    text-align: center;
   
}
figure{
    display: flex;
    flex-direction: column;
    background-color: white;
}

ul{
margin: 0 20%;
text-align: left;
}

li{
    margin: 15px 0;
}
img{
    display: block;
    border: 10px solid;
    border-color: white;
    margin-top: 10px;
    max-width:100%
}
.end{
    margin-top: 15px;
}

