    padding: 15px;
    border-radius: 5px;
    background: rgb(238, 238, 238);
    display: flex;
    flex-direction: column;
    text-align: center;
   
}
figure{
    display: flex;
    flex-direction: column;
    background-color: white;
}

ul{
margin: 0 20%;
text-align: left;
}

li{
