}
img{
    display: block;
    border: 10px solid;
    border-color: white;
    margin-top: 10px;
    max-width:100%
}
.end{
    margin-top: 15px;
}

#navbar{
    height:100%;
    width:300px;
    background-color: white;
    position:fixed;
    top:0;
    left: 0;
    border-right: 2px solid; 
    
}

#navbar header{
    text-align: center;
    padding:40px;
    font-size:2rem;
    font-weight: bold;
    background-color: brown;
}
#navbar li{
    text-transform: none;
    text-align: left;
    list-style: none;
    display: block;
    padding:20px;
    font-size:2rem;

}
#navbar li:hover{
    overflow: visible;
    transition: ease-in-out 200ms;
    background-color: gray;
}
#navbar li a{
    color:black;
    text-decoration: none;
    display: block;
}
#main-doc{
    height: 100%;
    margin-left: 310px;
    padding: 10px;
}
.up{
    text-transform: uppercase;
}
div{
    width: 100%;
    height: 10px;
    background-color: black;
}

@media screen and (max-width: 900px) {
    #navbar header{
    background-color: blue;
    }
}

body{
    margin: 0;
    padding: 0;
   background-image: url(../img/bg5.jpg); 
    

}
.beg{
    width: 200px;
    height: 50px;
    background-image: url(../img/vs.jpg);
    background-size:contain;
    background-repeat: no-repeat;
}

.title{
    position:fixed;
    top: 0;
    width: 100%;
    height: 50px;
   background-color: white; 
   color:black ;
   display: flex;
   justify-content: space-between;
   z-index: 20;
}
.ss{
   width: 50%;
   height: 100%;
   display: flex;
   justify-content: flex-end;
   gap: 40px;

}
.s1{
    width: 50px;
    height: 100px;
   background-image: url(../img/s3.png); 
   background-size: contain;
  background-repeat: no-repeat; 
}
.s2{
    width: 50px;
    height: 100px;
    background-image: url(../img/s2.png); 
    background-size: contain;
    background-repeat: no-repeat; 
 }
 .s3{
    width: 50px;
    height: 100px;
    background-image: url(../img/s4.png); 
    background-size: contain;
    background-repeat: no-repeat; 
 }
 .intro{
    display: flex;
    flex-direction: column;
    color:red;
    font-size: larger;
    font-weight: bolder;
    margin-top: 6% ;
    align-items: center;
    justify-content: center;
    line-height: 10px;
 }

.dd{
    width: 50px;
    height: 100px;
    background-color: red;
}
.op{
    list-style: none;
    display: flex;
    justify-content: space-around;
}
.op .box:nth-child(1){
    width: 40px;
    height: 50px;
    background-image: url(../img/sticker_29.png);
    background-size: contain;
   background-repeat: no-repeat; 
}
.op .box:nth-child(2){
    width: 40px;
    height: 50px;
    background-image: url(../img/sticker_29.png);
    background-size: contain;
   background-repeat: no-repeat; 
}
.op .box:nth-child(3){
    width: 40px;
    height: 50px;
    background-image: url(../img/sticker_29.png);
    background-size: contain;
   background-repeat: no-repeat; 
}
main{
    margin-top: 6%;
}
form{
    padding: 0;
    text-align: center;
    color: rgb(77, 4, 4);
}
hr{
    margin: 40px;
}
.st{
    display: flex;
    justify-content: center;
    gap: 20px;
     margin: 20px;
}
#r1{
    width: 300px;
    height: 300px;
   border: 2px solid; 
}
#r2{
    width: 300px;
    height: 300px;
   border: 2px solid; 
}
#r3{
    width: 300px;
    height: 300px;
   border: 2px solid; 
}
video{
    width:  500px ;
    height: 400px;
    border: 2px solid;
}
@media screen and (max-width: 400px){
    body{
        margin: 0;
        padding: 0;
       background-image: url(../img/bg3.jpg); 
    }
    main{
        margin-top: 15%;
    }
    .ss{
        width: 50%;
        height: 100%;
        display: flex;
        justify-content: flex-end;
        gap: 5px;
     
     }
}

*{
    padding: 0;
    margin: 0;
}
#welcome-section, #projects{
    height: 100vh;
    text-align: center;
    background-color: rgb(196, 190, 190);
    
}
h1,h2{
    position: relative;
    top: 20%;
    line-height: 1.6;
}
h1{
    color: red;
    font-weight: bolder;
}
h2{
    color:rgba(58, 38, 168, 0.808)
}
#projects{
   background: linear-gradient(black,red); 
   display: flex;
   flex-wrap: wrap;
    justify-content: center;
    align-items: center;
   gap: 20px;
     
}
.click{
    height:20px;
    border: 5px solid rgb(29, 28, 28);
    display: block;
   background-color: rgb(29, 28, 28); 

}
img{
    width: 300px;
    height: 300px;
    border: 5px solid rgb(29, 28, 28);
}
#navbar{
    width: 100%;
    height: 40px;
    position:fixed;
    top: 0;
    background-color: rgb(68, 24, 18);

}
ul{
    display: flex;
    justify-content: center;
    gap: 20px;

    

}
li{
list-style: none;
display: block;

}
li:hover{
   background-color: rosybrown;
    
    }
a{
    text-decoration: none;
    color: white;
}
@media screen and (max-width: 400px){
    img{
        width: 150px;
        height: 1500px;
        border: 5px solid rgb(29, 28, 28);
    }
   
}

